CREATE OR REPLACE FUNCTION public.operator_garage_overview(_garage_id uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
WITH own AS(SELECT id FROM garages WHERE id=_garage_id AND operator_id=auth.uid()),s AS(SELECT h.* FROM garage_request_stats_hourly h JOIN own ON own.id=h.garage_id),m AS(SELECT h.model,sum(h.requests) requests FROM garage_model_stats_hourly h JOIN own ON own.id=h.garage_id WHERE h.hour>=date_trunc('week',now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' GROUP BY h.model)
SELECT CASE WHEN EXISTS(SELECT 1 FROM own) THEN jsonb_build_object('today',coalesce((SELECT sum(spend_usd) FROM s WHERE hour>=date_trunc('day',now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'),0),'week',coalesce((SELECT sum(spend_usd) FROM s WHERE hour>=date_trunc('week',now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'),0),'total',coalesce((SELECT sum(spend_usd) FROM s),0),'last_request_hour',(SELECT max(hour) FROM s WHERE requests>0),'response_ms',(SELECT percentile_cont(0.5) WITHIN GROUP(ORDER BY ttft_ms_p50) FROM s WHERE hour>=now()-interval '7 days' AND ttft_ms_p50>0),'daily',(SELECT jsonb_agg(jsonb_build_object('day',d.day::date,'requests',coalesce((SELECT sum(requests) FROM s WHERE hour>=d.day AND hour<d.day+interval '1 day'),0)) ORDER BY d.day) FROM generate_series(date_trunc('day',now() AT TIME ZONE 'UTC')-interval '13 days',date_trunc('day',now() AT TIME ZONE 'UTC'),interval '1 day') d(day)),'models',coalesce((SELECT jsonb_agg(jsonb_build_object('model',model,'requests',requests)) FROM m),'[]'::jsonb)) END $$;
REVOKE ALL ON FUNCTION public.operator_garage_overview(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.operator_garage_overview(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.apply_smart_model_change(_garage_id uuid,_model text,_action text,_reason jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE g garages; event_id uuid; BEGIN
SELECT * INTO g FROM garages WHERE id=_garage_id FOR UPDATE;
IF g.id IS NULL OR NOT g.smart OR g.disabled OR g.paused_at IS NOT NULL OR g.created_at>now()-interval '24 hours' OR g.runtime IS DISTINCT FROM 'ollama' OR g.operator_id IS NULL THEN RETURN NULL; END IF;
IF EXISTS(SELECT 1 FROM garage_smart_events WHERE garage_id=g.id AND day=(now() AT TIME ZONE 'UTC')::date) OR EXISTS(SELECT 1 FROM garage_managed_models WHERE garage_id=g.id AND ((action='pull' AND status<>'ready') OR (action='remove' AND status<>'removed'))) THEN RETURN NULL; END IF;
IF _action='remove' AND NOT EXISTS(SELECT 1 FROM garage_managed_models WHERE garage_id=g.id AND model=_model AND "by"='garageai' AND action='pull' AND status='ready' AND requested_at<=now()-interval '14 days') THEN RETURN NULL; END IF;
IF _action='pull' AND (EXISTS(SELECT 1 FROM garage_models WHERE garage_id=g.id AND model=_model AND installed) OR EXISTS(SELECT 1 FROM garage_managed_models WHERE garage_id=g.id AND model=_model AND status<>'removed')) THEN RETURN NULL; END IF;
PERFORM apply_managed_model_request(g.id,_model,_action,'garageai');
INSERT INTO garage_smart_events(garage_id,operator_id,model,action,reason) VALUES(g.id,g.operator_id,_model,_action,_reason) RETURNING id INTO event_id; RETURN event_id; END $$;
REVOKE ALL ON FUNCTION public.apply_smart_model_change(uuid,text,text,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.apply_smart_model_change(uuid,text,text,jsonb) TO service_role;
CREATE OR REPLACE FUNCTION public.set_operator_model_prices(_garage_id uuid,_model text,_pool_input numeric,_pool_output numeric,_direct_input numeric,_direct_output numeric) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF NOT EXISTS(SELECT 1 FROM garages WHERE id=_garage_id AND operator_id=auth.uid() AND connection_type<>'endpoint') THEN RAISE EXCEPTION 'Not your garage'; END IF;
IF _pool_input IS NULL OR _pool_output IS NULL OR _direct_input IS NULL OR _direct_output IS NULL OR least(_pool_input,_pool_output,_direct_input,_direct_output)<0 OR greatest(_pool_input,_pool_output,_direct_input,_direct_output)>10000 THEN RAISE EXCEPTION 'Invalid prices'; END IF;
UPDATE garage_models SET pool_input_cost_per_million=_pool_input,pool_output_cost_per_million=_pool_output,dedicated_input_cost_per_million=_direct_input,dedicated_output_cost_per_million=_direct_output WHERE garage_id=_garage_id AND model=_model;
IF NOT FOUND THEN RAISE EXCEPTION 'Model not found'; END IF;
INSERT INTO garage_price_history(garage_id,prices,changed_by) VALUES(_garage_id,jsonb_build_object('model',_model,'pool_input_cost_per_million',_pool_input,'pool_output_cost_per_million',_pool_output,'dedicated_input_cost_per_million',_direct_input,'dedicated_output_cost_per_million',_direct_output),auth.uid()); END $$;
REVOKE ALL ON FUNCTION public.set_operator_model_prices(uuid,text,numeric,numeric,numeric,numeric) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.set_operator_model_prices(uuid,text,numeric,numeric,numeric,numeric) TO authenticated;